item.text:
{
  "repair_case_id": "RC-0103",
  "role": "accountability_advocate",
  "role_contract_version": "0.1",
  "findings": [
    {
      "finding_id": "F1",
      "statement": "H1 is established; H2–H4 are substantially established. The packet establishes institutional responsibility but only attributes individual responsibility. No individual guilt follows from employment, citizenship or political affiliation.",
      "basis": "packet",
      "harm_ids": ["H1", "H2", "H3", "H4"],
      "source_ids": ["/repair_packet/established_harms", "/repair_packet/responsible_actors"],
      "materiality": "decisive"
    },
    {
      "finding_id": "F2",
      "statement": "Conditional individual amnesty can contribute to legitimate repair if independently verified disclosure produces otherwise difficult-to-obtain truth, accountability remains enforceable outside its narrow scope, and victims receive substantive remedies. Amnesty itself neither repairs injury nor justifies the original violations.",
      "basis": "constitutional_interpretation",
      "harm_ids": ["H1", "H2", "H3", "H4"],
      "source_ids": ["MC-01", "MC-04", "MC-08", "MC-11", "IR-02"],
      "materiality": "decisive"
    },
    {
      "finding_id": "F3",
      "statement": "Practical prosecution limits do not establish that amnesty is necessary or that particular prosecutions are infeasible. Additional disclosure, deterrence and peace benefits remain uncertain; political inconvenience alone cannot justify immunity.",
      "basis": "packet",
      "harm_ids": ["H3", "H4"],
      "source_ids": ["/repair_packet/constraints", "/repair_packet/uncertainties"],
      "materiality": "high"
    },
    {
      "finding_id": "F4",
      "statement": "Victims disagree about amnesty. Notice, representation, opportunities to challenge disclosure, reasoned decisions and review must preserve their standing without requiring forgiveness or treating any representative as speaking for all.",
      "basis": "constitutional_interpretation",
      "harm_ids": ["H1", "H2"],
      "source_ids": ["/repair_packet/affected_parties", "MC-03", "MC-06", "MC-11"],
      "materiality": "high"
    },
    {
      "finding_id": "F5",
      "statement": "The packet does not specify representation for people unable or unwilling to testify, threatened witnesses, or people implicated by another applicant's disclosure. Their protection and opportunity to contest adverse findings require explicit provision.",
      "basis": "missing_information",
      "source_ids": ["/repair_packet/affected_parties", "/repair_packet/repair_options"],
      "materiality": "high"
    }
  ],
  "principle_assessments": [
    {
      "principle_id": "MC-01",
      "status": "conflict",
      "reason": "Public peace is legitimate, but victims cannot be made disposable instruments of a settlement; their independent claims survive amnesty."
    },
    {
      "principle_id": "MC-02",
      "status": "supports_component",
      "reason": "Protection, treatment and prevention of renewed violence support repair; punishment must not pursue suffering or humiliation."
    },
    {
      "principle_id": "MC-03",
      "status": "supports_component",
      "reason": "Testimony, treatment and reconciliation require meaningful choice; assistance cannot depend on forgiveness."
    },
    {
      "principle_id": "MC-04",
      "status": "supports_component",
      "reason": "Independent corroboration and explicit uncertainty are essential because applicants have incentives to minimise responsibility."
    },
    {
      "principle_id": "MC-05",
      "status": "concern",
      "reason": "Apply identical evidentiary and eligibility standards across affiliations while accurately describing differing institutional roles and patterns of abuse."
    },
    {
      "principle_id": "MC-06",
      "status": "supports_component",
      "reason": "Low-power victims need accessible representation, protection and remedies to participate effectively."
    },
    {
      "principle_id": "MC-07",
      "status": "conflict",
      "reason": "Society receives transition benefits while victims bear lost opportunities for punishment; public funding of repair is required but cannot eliminate that burden."
    },
    {
      "principle_id": "MC-08",
      "status": "supports_component",
      "reason": "Truth, restitution, compensation, rehabilitation and proportionate accountability serve repair without making maximum punishment the measure of justice."
    },
    {
      "principle_id": "MC-10",
      "status": "supports_component",
      "reason": "Investigative powers and protective restrictions require necessity, proportionality, narrow scope and independent review."
    },
    {
      "principle_id": "MC-11",
      "status": "supports_component",
      "reason": "Neither implicated institutions nor applicants may judge their own compliance; decisions require evidence, reasons, challenge and correction."
    },
    {
      "principle_id": "MC-12",
      "status": "supports_component",
      "reason": "Preserve criticism of amnesty and review the programme against disclosure, remedy delivery and recurrence evidence."
    }
  ],
  "component_assessments": [
    {
      "component_type": "truth_acknowledgement",
      "status": "required",
      "reason": "Use an independent commission with lawful investigative powers, corroboration, protected records and public reasoned findings. Distinguish allegations from established findings and allow implicated people to respond.",
      "option_ids": ["R1"]
    },
    {
      "component_type": "amnesty",
      "status": "permissible",
      "reason": "Require individual applications identifying specific acts, full disclosure of involvement and known responsibility, records and locations, independent verification, and reasoned review. Define political nexus through evidence of objectives, context and connection of acts to those objectives; affiliation or assertion alone is insufficient. Exclude private criminality. Limit immunity to specified qualifying acts, with predefined revocation for material concealment or fraud after due process. Establish applicable legal limits before granting immunity; the packet does not resolve them.",
      "option_ids": ["R2"]
    },
    {
      "component_type": "accountability",
      "status": "required",
      "reason": "Resource independent investigation and prosecution or civil proceedings for non-applicants, rejected applicants, revoked grants and uncovered acts where evidence supports action. Failure to qualify is not proof of guilt. Preserve defence rights, applicable proof standards, appeal and proportionate sanctions; publish follow-through so enforcement is credible.",
      "option_ids": ["R3"]
    },
    {
      "component_type": "protection",
      "status": "required",
      "reason": "Provide witness protection, confidential participation, legal assistance and trauma-sensitive hearings. Offer victims notice, opportunities to challenge applications and access to independent review.",
      "option_ids": ["R1", "R2", "R5"]
    },
    {
      "component_type": "compensation",
      "status": "required",
      "reason": "Fund a timely reparation programme with fair eligibility, accessible proof rules accounting for destroyed evidence, transparent priorities and appeals. Remedies must not depend on testimony, an offender's application or forgiveness; amounts remain feasibility-dependent.",
      "option_ids": ["R4"]
    },
    {
      "component_type": "rehabilitation",
      "status": "required",
      "reason": "Provide voluntary medical, psychological and social support for continuing harm. Any perpetrator rehabilitation should complement responsibility and assessed safety, without requiring victim contact.",
      "option_ids": ["R5"]
    },
    {
      "component_type": "restitution",
      "status": "required",
      "reason": "Pursue records, remains, status and property restoration wherever feasible, respecting family choices. Death and lost years cannot be restored.",
      "option_ids": ["R6"]
    },
    {
      "component_type": "institutional_reform",
      "status": "required",
      "reason": "Reform implicated institutions through independent oversight and evidence-based personnel decisions. The successor state has repair duties without inheriting personal guilt.",
      "option_ids": ["R7"]
    },
    {
      "component_type": "restriction",
      "status": "insufficient_evidence",
      "reason": "No particular person's continuing danger is established. Any protective restriction requires individual evidence, necessity, proportionality and review; amnesty must not confer entitlement to positions enabling renewed abuse."
    },
    {
      "component_type": "non_recurrence",
      "status": "required",
      "reason": "Monitor intimidation, renewed abuse, enforcement and reform implementation; do not assume either amnesty or severe punishment guarantees deterrence.",
      "option_ids": ["R3", "R7"]
    },
    {
      "component_type": "memorialisation",
      "status": "recommended",
      "reason": "Preserve an accurate, accessible record with privacy safeguards and space for dissent; memorials cannot discharge material repair obligations.",
      "option_ids": ["R8"]
    },
    {
      "component_type": "reconciliation",
      "status": "permissible",
      "reason": "Support only voluntary reconciliation. Victims retain the right to reject forgiveness, contact and narratives of national closure.",
      "option_ids": ["R9"]
    },
    {
      "component_type": "other",
      "status": "concern",
      "reason": "Prosecution-led R10 remains a serious alternative. Its comparative truth yield and practical reach are unknown; assess it before concluding that immunity is necessary.",
      "option_ids": ["R10"]
    }
  ],
  "failure_risks": [
    {
      "risk": "revenge",
      "status": "possible",
      "reason": "Accountability could become retaliatory if punishment pursues suffering rather than proportionate justice and protection."
    },
    {
      "risk": "impunity",
      "status": "serious",
      "reason": "Unverified disclosure, expansive political nexus or unfunded prosecution would convert conditional amnesty into effective blanket immunity."
    },
    {
      "risk": "forced_forgiveness",
      "status": "serious",
      "reason": "A unity narrative could pressure victims to forgive or make assistance depend on reconciliation."
    },
    {
      "risk": "inherited_or_category_guilt",
      "status": "possible",
      "reason": "Established institutional abuse must not substitute for proof against individual officials, citizens or organisation members."
    },
    {
      "risk": "symbolic_only_repair",
      "status": "serious",
      "reason": "Collecting testimony without delivering feasible material remedies would exploit victims' participation."
    },
    {
      "risk": "victim_voice_erasure",
      "status": "serious",
      "reason": "Treating selected supporters as a victim consensus would suppress legitimate opposition to amnesty."
    },
    {
      "risk": "unsafe_reintegration",
      "status": "uncertain",
      "reason": "Individual danger is unspecified; legal immunity alone does not establish safe return to coercive authority."
    }
  ],
  "recommended_components": [
    "Implement R1 with independent investigation, protected participation and contestable findings.",
    "Permit R2 only under narrow, published, verified and reviewable criteria, after examining less immunity-dependent alternatives.",
    "Resource R3 and enforce consequences for disqualification, material deception and acts outside granted immunity.",
    "Deliver R4, R5 and feasible R6 through enforceable programmes independent of forgiveness.",
    "Implement R7 with community oversight and monitored non-recurrence outcomes.",
    "Support R8 and strictly voluntary R9 without treating either as moral closure."
  ],
  "information_requests": [
    "What legal limits, political-nexus tests, disclosure standards, evidentiary-use rules and review or revocation procedures would govern applications?",
    "What investigative resources, independent evidence and prosecution capacity exist for major violations and rejected applications?",
    "How will diverse victims, non-testifying survivors, threatened witnesses and implicated individuals obtain representation and protection?",
    "What funded reparation commitments, delivery deadlines and institutional reforms are enforceable?"
  ],
  "evidence_that_could_change_view": [
    "Credible evidence that comparable truth and feasible accountability are obtainable without amnesty would weaken its justification.",
    "Verified substantial new disclosure unavailable through realistic alternatives would strengthen narrowly conditional amnesty.",
    "Systematic deception, political favouritism, intimidation or failure to prosecute eligible cases would undermine the arrangement.",
    "Evidence of undelivered reparations, excluded victim perspectives or continuing institutional abuse would require redesign.",
    "Sustained evidence on recurrence and rule-of-law effects could justify revising future eligibility and safeguards."
  ],
  "unresolved_objections": [
    "The strongest objection is that even truthful, procedurally valid amnesty can deny victims deserved adjudication and proportionate punishment for grave violations, rewarding perpetrators for controlling information they wrongfully withheld. Public benefits and compensation do not fully answer that unequal burden.",
    "Credible incentives require predictable legal consequences, yet incomplete evidence may reveal deception only after immunity is granted. Clear scope and predefined review grounds reduce, but do not eliminate, this tension.",
    "The packet does not establish that enough additional truth or protection will result to justify foregoing otherwise feasible accountability."
  ]
}
